package vn.ticketscenter.config.worker;
import vn.ticketscenter.config.persistence.*;import java.util.*;
public final class HoldExpiryJob {private final TransactionManager tx;public HoldExpiryJob(TransactionManager tx){this.tx=tx;}public int runOnce(){return tx.execute(DatabasePrincipal.WORKER,em->{List<UUID> ids=em.createNativeQuery("SELECT id FROM dbo.tc_ticket_holds WHERE status='ACTIVE' AND expires_at<=SYSUTCDATETIME()").getResultList().stream().map(x->(UUID)x).toList();for(UUID id:ids){var q=em.createStoredProcedureQuery("dbo.usp_ReleaseTicketHold").registerStoredProcedureParameter("hold_id",UUID.class,jakarta.persistence.ParameterMode.IN).registerStoredProcedureParameter("actor_id",UUID.class,jakarta.persistence.ParameterMode.IN).registerStoredProcedureParameter("reason",String.class,jakarta.persistence.ParameterMode.IN).setParameter("hold_id",id).setParameter("actor_id",null).setParameter("reason","EXPIRED");q.execute();}return ids.size();});}}
